import json,time,urllib.request,urllib.error
from datetime import datetime,timezone
B='http://localhost:8080';tok=None;log=set()
def get(path):
    global tok
    for _ in range(200):
        try:
            if tok is None:
                tok=json.load(urllib.request.urlopen(urllib.request.Request(B+'/token',method='POST')))['token']
            r=urllib.request.Request(B+path,headers={'Authorization':'Bearer '+tok})
            return json.load(urllib.request.urlopen(r,timeout=30))
        except urllib.error.HTTPError as e:
            body=e.read()[:200]; log.add((e.code,))
            if e.code==404: return None
            if e.code==401: tok=None; continue
            w=e.headers.get('Retry-After')
            try: w=float(w)
            except: 
                try: w=float(json.loads(body).get('retry_after',1))
                except: w=1
            print(e.code,w,body);time.sleep(w+0.1)
        except Exception as ex:
            print('err',ex);time.sleep(1)
    raise SystemExit('fail '+path)
seen={};dups=0;p=1
while True:
    d=get(f'/orders?page={p}')
    for o in d['items']:
        if o['id'] in seen:
            dups+=1
            if seen[o['id']]!=o: print('differs',o['id'])
        else: seen[o['id']]=o
    if not d['next']: break
    p+=1
print(p,d['total_pages'],len(seen),dups)
lo=datetime(2025,3,1,tzinfo=timezone.utc);hi=datetime(2025,6,1,tzinfo=timezone.utc)
cust={};tot=0;n=0;reg={'north':0,'south':0,'east':0,'west':0}
for o in seen.values():
    if o['status']!='shipped':continue
    t=datetime.fromisoformat(o['placed_at'].replace('Z','+00:00'))
    if t.tzinfo is None: print('naive',o);t=t.replace(tzinfo=timezone.utc)
    if not(lo<=t<hi):continue
    c=o['customer_id']
    if c not in cust: cust[c]=get('/customers/'+c)
    if cust[c] is None: print('missing cust',o);continue
    a=o['amount_cents']*(100-cust[c]['discount_pct']);v=(a+50)//100
    reg[cust[c]['region']]+=v;tot+=v;n+=1
print(tot,n,reg,log)
json.dump({'total_cents':tot,'order_count':n,'duplicates_skipped':dups,'by_region':reg},open('/workspace/result.json','w'),indent=2)
